import numpy as np
from alphacrafter.sim.utils import (
    register_hook, get_account_dict, get_stock_daily_data, rebalance_to_weights,
)

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX",
          "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
FACTOR_W = {"clv": 0.3395, "peer": 0.2612, "reversal": 0.2012, "momentum": 0.1981}
MIN_W, MAX_W = 0.015, 0.16
_day = 0


def cs_rank(values):
    out = {s: 0.5 for s in ASSETS}
    valid = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    n = len(valid)
    if n > 1:
        for i, (s, _) in enumerate(valid):
            out[s] = (i + 1.0) / n
    return out


def bounded_simplex(raw):
    # Iterative water-filling; guarantees a complete, cash-free target.
    w = {s: max(float(raw.get(s, 0.01)), 1e-9) for s in ASSETS}
    w = {s: v / sum(w.values()) for s, v in w.items()}
    fixed = {}
    for _ in range(30):
        free = [s for s in ASSETS if s not in fixed]
        if not free:
            break
        remain = 1.0 - sum(fixed.values())
        base = sum(w[s] for s in free)
        changed = False
        for s in free:
            candidate = remain * w[s] / base
            if candidate < MIN_W:
                fixed[s] = MIN_W; changed = True
            elif candidate > MAX_W:
                fixed[s] = MAX_W; changed = True
        if not changed:
            for s in free:
                w[s] = remain * w[s] / base
            break
    w.update(fixed)
    total = sum(w.values())
    return {s: float(w[s] / total) for s in ASSETS}


@register_hook
def cross_asset_strategy():
    global _day
    _day += 1
    account = get_account_dict()
    positions = account.get("positions", [])
    # Rebalance on the first decision and then once per ten trading days.
    if positions and (_day - 1) % 10 != 0:
        return

    data = {}
    for symbol in ASSETS:
        df = get_stock_daily_data(symbol=symbol, days=90)
        if df is None or len(df) < 30:
            continue
        df = df.sort_values("date").reset_index(drop=True)
        close = np.asarray(df["close"], dtype=float)
        high = np.asarray(df["high"], dtype=float)
        low = np.asarray(df["low"], dtype=float)
        ret = close[1:] / np.maximum(close[:-1], 1e-12) - 1.0
        vol = max(float(np.std(ret[-20:])), 0.008)
        data[symbol] = (close, high, low, ret, vol)
    if len(data) < 12:
        return

    clv, peer, reversal, momentum, invvol = {}, {}, {}, {}, {}
    for s, (c, h, l, r, vol) in data.items():
        spread = max(float(h[-1] - l[-1]), 1e-12)
        clv[s] = (2.0 * c[-1] - h[-1] - l[-1]) / spread
        peer[s] = c[-1] / max(c[-6], 1e-12) - 1.0
        reversal[s] = -float(np.mean(r[-5:]))
        momentum[s] = (c[-1] / max(c[-21], 1e-12) - 1.0) / (vol + 0.01)
        invvol[s] = 1.0 / vol
    # Lead-lag is relative to the available cross-section, avoiding macro orders.
    peer_med = float(np.median(list(peer.values())))
    peer = {s: v - peer_med for s, v in peer.items()}
    ranked = {k: cs_rank(v) for k, v in {
        "clv": clv, "peer": peer, "reversal": reversal, "momentum": momentum
    }.items()}
    score = {s: sum(FACTOR_W[k] * ranked[k][s] for k in FACTOR_W) for s in ASSETS}

    # Bear regime: express risk reduction only through tradable defensives.
    if "SPX" in data:
        spx = data["SPX"][0]
        if spx[-1] < spx[-21] and spx[-1] < spx[-6]:
            for s in ("XAU", "US10Y", "CN10Y"):
                score[s] += 0.18
            for s in ("BTC", "ETH", "WTI"):
                score[s] = max(0.03, score[s] - 0.10)

    avg_iv = float(np.mean(list(invvol.values())))
    raw = {s: max(score[s], 0.01) *
              (0.78 + 0.22 * invvol.get(s, avg_iv) / max(avg_iv, 1e-12))
           for s in ASSETS}
    rebalance_to_weights(bounded_simplex(raw))

