import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
# Screener ensemble: capped at seven active factors and normalized to one.
FACTORS = {"clv1": .240, "leadlag5": .210, "rev5": .170, "mom20": .160,
           "down20": .085, "rev3": .075, "clvtrend15": .060}
MIN_W, MAX_W = .02, .15
_day = 0


def rank_cs(vals):
    out = {s: .5 for s in ASSETS}
    good = sorted((s, float(v)) for s, v in vals.items() if np.isfinite(v))
    n = len(good)
    if n > 1:
        for i, (s, _) in enumerate(good):
            out[s] = (i + 1.0) / n
    return out


def bounded_weights(score):
    # Positive score transform, with a small universal allocation and 15% cap.
    w = {s: MIN_W for s in ASSETS}
    free, active = 1.0 - MIN_W * len(ASSETS), set(ASSETS)
    while active:
        q = {s: max(float(score.get(s, .5)), .01) for s in active}
        total = sum(q.values())
        hit = [s for s in active if free * q[s] / total > MAX_W - MIN_W]
        if not hit:
            for s in active:
                w[s] += free * q[s] / total
            break
        for s in hit:
            w[s] = MAX_W
            free -= MAX_W - MIN_W
            active.remove(s)
        if free <= 1e-12:
            break
    z = sum(w.values())
    return {s: w[s] / z for s in ASSETS}


@register_hook
def cross_asset_strategy():
    global _day
    _day += 1
    # Decisions are made only on the first day of each ten-trading-day block.
    if (_day - 1) % 10:
        return

    data = {}
    for symbol in ASSETS:
        df = get_stock_daily_data(symbol=symbol, days=100)
        if df is None or len(df) < 35:
            continue
        df = df.sort_values("date")
        c = np.asarray(df["close"], dtype=float)
        h = np.asarray(df["high"], dtype=float)
        lo = np.asarray(df["low"], dtype=float)
        if len(c) < 32 or not np.all(np.isfinite(c[-32:])) or c[-1] <= 0:
            continue
        ret = c[1:] / np.maximum(c[:-1], 1e-12) - 1.0
        vol = max(float(np.std(ret[-20:])), .008)
        downside = max(float(np.std(np.minimum(ret[-20:], 0.0))), .004)
        rng = np.maximum(h[-15:] - lo[-15:], 1e-12)
        clv_hist = (2.0 * c[-15:] - h[-15:] - lo[-15:]) / rng
        clv = (2.0 * c[-1] - h[-1] - lo[-1]) / max(h[-1] - lo[-1], 1e-12)
        data[symbol] = {
            "clv1": clv, "r5": c[-1] / c[-6] - 1.0,
            "rev5": -float(np.mean(ret[-5:])), "rev3": -float(np.mean(ret[-3:])),
            "mom20": (c[-1] / c[-21] - 1.0) / (vol + .01),
            "down20": (c[-1] / c[-21] - 1.0) / (downside + .01),
            "clvtrend15": float(np.mean(clv_hist)), "trend": c[-1] / c[-31] - 1.0,
            "invvol": 1.0 / vol,
        }
    if len(data) < 10:
        return

    # Robust cross-sectional proxies for the persisted factor definitions.
    peer_median = float(np.median([v["r5"] for v in data.values()]))
    raw = {f: {} for f in FACTORS}
    for s, v in data.items():
        raw["clv1"][s] = v["clv1"]
        raw["leadlag5"][s] = v["r5"] - peer_median
        raw["rev5"][s], raw["mom20"], raw["down20"] = v["rev5"], v["mom20"], v["down20"]
        raw["rev3"][s], raw["clvtrend15"] = v["rev3"], v["clvtrend15"]
    ranks = {f: rank_cs(raw[f]) for f in FACTORS}
    score = {s: sum(FACTORS[f] * ranks[f][s] for f in FACTORS) for s in ASSETS}

    # Medium-high risk regime: use tradable defensive assets, never cash.
    eq = [data[s] for s in ("000300.SH", "SPX", "HSI", "N225", "SX5E", "NDX") if s in data]
    spx = data.get("SPX", {})
    bear = (len(eq) >= 3 and sum(x["trend"] < 0 for x in eq) / len(eq) >= .5) or (spx.get("trend", 0) < 0 and spx.get("r5", 0) < 0)
    if bear:
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] = score.get(s, .5) + .10
        for s in ("BTC", "ETH", "WTI"):
            score[s] = max(.02, score.get(s, .5) - .05)

    # Mild inverse-volatility tilt limits unstable-asset concentration.
    median_invvol = float(np.median([v["invvol"] for v in data.values()]))
    for s in ASSETS:
        iv = data.get(s, {}).get("invvol", median_invvol)
        score[s] = max(.02, score[s]) * (.94 + .06 * iv / max(median_invvol, 1e-12))
    target = bounded_weights(score)
    if abs(sum(target.values()) - 1.0) < 1e-8 and all(np.isfinite(v) and v >= 0 for v in target.values()):
        rebalance_to_weights(target)

