import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
# Current Screener ensemble: eight active, positive-direction factors.
FACTORS = {"downmom": .26, "eff": .24, "lead": .15, "mom20": .08,
           "persist": .08, "resid30": .07, "mom30": .07, "rev": .05}
MIN_W, MAX_W = .025, .16
_day = 0


def cs_rank(values):
    out = {s: .5 for s in ASSETS}
    valid = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    n = len(valid)
    for i, (s, _) in enumerate(valid):
        out[s] = (i + 1.0) / n if n > 1 else .5
    return out


def make_weights(score):
    # Full investment, mild floor and cap; fractional quantities are handled by helper.
    raw = {s: max(.05, float(score.get(s, .5))) for s in ASSETS}
    free_total = 1.0 - MIN_W * len(ASSETS)
    w = {s: MIN_W + free_total * raw[s] / sum(raw.values()) for s in ASSETS}
    for _ in range(30):
        capped = [s for s in ASSETS if w[s] > MAX_W]
        if not capped:
            break
        excess = sum(w[s] - MAX_W for s in capped)
        for s in capped:
            w[s] = MAX_W
        free = [s for s in ASSETS if s not in capped]
        if not free:
            break
        den = sum(raw[s] for s in free)
        for s in free:
            w[s] += excess * raw[s] / den
    total = sum(w.values())
    return {s: max(0.0, w[s] / total) for s in ASSETS}


@register_hook
def cross_asset_strategy():
    global _day
    _day += 1
    if (_day - 1) % 10 != 0:
        return

    data = {}
    for s in ASSETS:
        df = get_stock_daily_data(symbol=s, days=180)
        if df is None or len(df) < 65:
            continue
        close = np.asarray(df.sort_values("date")["close"], dtype=float)
        if len(close) < 65 or not np.all(np.isfinite(close[-65:])) or np.any(close[-65:] <= 0):
            continue
        r = close[1:] / close[:-1] - 1.0
        vol = max(float(np.std(r[-20:])), .008)
        downside = max(float(np.std(np.minimum(r[-20:], 0.0))), .004)
        t20 = close[-1] / close[-21] - 1.0
        t30 = close[-1] / close[-31] - 1.0
        t5 = close[-1] / close[-6] - 1.0
        data[s] = {"downmom": t20 / (downside + .01),
                   "eff": t20 / (downside + .015),
                   "lead_raw": t5, "mom20": t20 / (vol + .01) * (.5 + np.mean(r[-20:] > 0)),
                   "persist": t30 / (vol + .01) * np.mean(r[-30:] > 0),
                   "mom30": t30 / (vol + .01) * (.5 + np.mean(r[-30:] > 0)),
                   "rev": -float(np.mean(r[-5:])), "trend": t30, "vol": vol}

    if len(data) < 10:
        return
    median_5 = float(np.median([x["lead_raw"] for x in data.values()]))
    median_30 = float(np.median([x["trend"] for x in data.values()]))
    for s, x in data.items():
        x["lead"] = x["lead_raw"] - median_5
        x["resid30"] = x["trend"] - median_30

    ranks = {f: cs_rank({s: x[f] for s, x in data.items()}) for f in FACTORS}
    score = {s: sum(FACTORS[f] * ranks[f][s] for f in FACTORS) for s in ASSETS}

    # Bear/high-risk regime: defensive tradable assets replace a cash sleeve.
    eq = [data[s] for s in ["000300.SH", "SPX", "HSI", "N225", "SX5E", "NDX"] if s in data]
    breadth = sum(x["trend"] > 0 for x in eq) / max(1, len(eq))
    spx = data.get("SPX", {})
    median_vol = float(np.median([x["vol"] for x in data.values()]))
    bear = len(eq) >= 3 and (breadth <= .50 or (spx.get("trend", 0) < 0 and spx.get("lead", 0) < 0))
    high_risk = median_vol > .018 or breadth < .67
    if bear or high_risk:
        boost = .16 if bear else .10
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] += boost
        for s in ("BTC", "ETH", "WTI"):
            score[s] = max(.05, score[s] - (.08 if bear else .04))

    # Small inverse-volatility adjustment prevents a single defensive winner dominating.
    for s in ASSETS:
        if s in data:
            score[s] *= .985 + .015 * median_vol / max(data[s]["vol"], .004)
    rebalance_to_weights(make_weights(score))


def strategy():
    return cross_asset_strategy()

