import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
# Screener ensemble: six validated, directional factors; capped below ten.
FACTORS = {"cons20": 0.34, "cons30": 0.22, "downmom": 0.14,
           "eff": 0.12, "persist30": 0.10, "resid": 0.08}
MIN_W, MAX_W = 0.03, 0.15
_day = 0


def cs_rank(vals):
    out = {s: 0.5 for s in ASSETS}
    good = sorted((s, float(v)) for s, v in vals.items() if np.isfinite(v))
    if len(good) > 1:
        for i, (s, _) in enumerate(good):
            out[s] = (i + 1.0) / len(good)
    elif good:
        out[good[0][0]] = 0.5
    return out


def bounded(score):
    # 3%-15% bounds, then normalize to an exact full-investment vector.
    raw = {s: max(0.05, float(score.get(s, 0.5))) for s in ASSETS}
    free_budget = 1.0 - MIN_W * len(ASSETS)
    w = {s: MIN_W + free_budget * raw[s] / sum(raw.values()) for s in ASSETS}
    for _ in range(20):
        capped = [s for s in ASSETS if w[s] > MAX_W]
        if not capped:
            break
        excess = sum(w[s] - MAX_W for s in capped)
        for s in capped:
            w[s] = MAX_W
        free = [s for s in ASSETS if s not in capped]
        den = sum(raw[s] for s in free)
        if not free or den <= 0:
            break
        for s in free:
            w[s] += excess * raw[s] / den
    total = sum(w.values())
    return {s: max(0.0, w[s] / total) for s in ASSETS}


@register_hook
def cross_asset_strategy():
    global _day
    _day += 1
    if (_day - 1) % 10 != 0:
        return

    data = {}
    for s in ASSETS:
        df = get_stock_daily_data(symbol=s, days=190)
        if df is None or len(df) < 65:
            continue
        df = df.sort_values("date")
        c = np.asarray(df["close"], dtype=float)
        h = np.asarray(df["high"], dtype=float)
        l = np.asarray(df["low"], dtype=float)
        if np.any(~np.isfinite(c[-65:])) or np.any(c[-65:] <= 0):
            continue
        r = c[1:] / c[:-1] - 1.0
        v20 = max(float(np.std(r[-20:])), 0.006)
        dn20 = max(float(np.std(np.minimum(r[-20:], 0.0))), 0.003)
        t20 = c[-1] / c[-21] - 1.0
        t30 = c[-1] / c[-31] - 1.0
        p20 = float(np.mean(r[-20:] > 0))
        p30 = float(np.mean(r[-30:] > 0))
        rr = np.maximum(h[-30:] - l[-30:], c[-30:] * 0.001) / c[-30:]
        range_rate = max(float(np.mean(rr)), 0.002)
        data[s] = {
            "cons20": t20 / (v20 + 0.01) * (0.5 + p20),
            "cons30": t30 / (v20 + 0.01) * (0.5 + p30),
            "downmom": t20 / (dn20 + 0.01),
            "eff": t20 / (dn20 + 0.015),
            "persist30": t30 / (range_rate + 0.01) * (0.5 + p30),
            "t30": t30, "vol": v20,
        }
    if len(data) < 10:
        return

    median_t30 = float(np.median([x["t30"] for x in data.values()]))
    for x in data.values():
        x["resid"] = x["t30"] - median_t30
    ranks = {f: cs_rank({s: x[f] for s, x in data.items()}) for f in FACTORS}
    score = {s: sum(FACTORS[f] * ranks[f][s] for f in FACTORS) for s in ASSETS}

    # Fragile sideways/bullish regime: stay fully invested, but use tradable
    # defensive assets rather than cash. Adjustments are deliberately modest.
    eq_names = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX"]
    eq = [data[s] for s in eq_names if s in data]
    breadth = float(np.mean([x["t30"] > 0 for x in eq])) if eq else 0.5
    medvol = float(np.median([x["vol"] for x in data.values()]))
    spx = data.get("SPX", {"t30": 0.0, "resid": 0.0})
    defensive = breadth < 0.67 or medvol > 0.018 or (spx["t30"] < 0 and spx["resid"] < 0)
    if defensive:
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] += 0.07
        for s in ("BTC", "ETH", "WTI"):
            score[s] = max(0.05, score[s] - 0.035)

    # Mild inverse-volatility scaling limits concentration without changing
    # factor direction; rank score remains the primary signal.
    for s in ASSETS:
        if s in data:
            score[s] *= 0.99 + 0.01 * medvol / max(data[s]["vol"], 0.004)
    rebalance_to_weights(bounded(score))


def strategy():
    return cross_asset_strategy()

