import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, get_index_daily_data, rebalance_to_weights

ASSETS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
# Screener's current eight-factor quality_ic_tilt ensemble (all positive direction).
FACTORS = {"mom20": .25, "mom30": .20, "persist30": .15, "mktres": .12,
           "cons20": .10, "rev5": .08, "shock1": .05, "smoothrev1": .05}
REBALANCE_DAYS = 10
POSITION_SCALING = 0.045
MIN_W, MAX_W = 0.04, 0.14
_day = 0


def rank_cs(values):
    out = {s: 0.5 for s in ASSETS}
    a = sorted((s, v) for s, v in values.items() if np.isfinite(v))
    if not a:
        return out
    for i, (s, _) in enumerate(a):
        out[s] = (i + 1.0) / len(a)
    return out


def make_weights(score, invvol):
    raw = {s: max(0.05, 0.5 + POSITION_SCALING * (score[s] - 0.5)) *
              np.clip(invvol.get(s, 1.0), 0.70, 1.30) for s in ASSETS}
    # A 4% floor keeps the online account fully invested in every tradable asset.
    w = {s: MIN_W + (1 - len(ASSETS) * MIN_W) * raw[s] / sum(raw.values()) for s in ASSETS}
    for _ in range(30):
        high = [s for s in ASSETS if w[s] > MAX_W + 1e-10]
        if not high:
            break
        excess = sum(w[s] - MAX_W for s in high)
        for s in high:
            w[s] = MAX_W
        rest = [s for s in ASSETS if s not in high]
        z = sum(raw[s] for s in rest)
        if not rest or z <= 0:
            break
        for s in rest:
            w[s] += excess * raw[s] / z
    z = sum(w.values())
    return {s: max(0.0, w[s] / z) for s in ASSETS}


@register_hook
def cross_asset_strategy():
    global _day
    _day += 1
    if (_day - 1) % REBALANCE_DAYS:
        return
    feat, rets = {}, {}
    for s in ASSETS:
        df = get_stock_daily_data(symbol=s, days=170)
        if df is None or len(df) < 75:
            continue
        d = df.sort_values("date").iloc[:-1]  # lag: never use the incomplete/current bar
        c = np.asarray(d["close"], dtype=float)
        if len(c) < 65 or np.any(~np.isfinite(c[-65:])) or np.any(c[-65:] <= 0):
            continue
        r = c[1:] / c[:-1] - 1.0
        r20, r30 = r[-20:], r[-30:]
        vol = max(float(np.std(r20)), 0.006)
        t20, t30 = c[-1] / c[-21] - 1.0, c[-1] / c[-31] - 1.0
        # Positive reversal means recent losers are preferred, but only modestly.
        rev5 = -float(np.sum(r[-5:])) / (vol + .01)
        shock1 = -float(r[-1]) / (vol + .01)
        smoothrev1 = -float(np.mean(r[-3:])) / (vol + .01)
        high = np.asarray(d["high"].iloc[-10:], float) if "high" in d else c[-10:]
        low = np.asarray(d["low"].iloc[-10:], float) if "low" in d else c[-10:]
        clv = np.mean(np.where(high > low, (2*c[-10:]-high-low)/(high-low), 0.0))
        feat[s] = {"mom20": t20/(vol+.01), "mom30": t30/(vol+.01),
                   "persist30": t30/(vol+.01)*(.5+.5*np.mean(r30 > 0)),
                   "cons20": float(np.mean(r20 > 0)), "rev5": rev5,
                   "shock1": shock1, "smoothrev1": smoothrev1,
                   "t30": t30, "vol": vol, "clv": float(clv)}
        rets[s] = r[-30:]
    if len(feat) < 10:
        return

    # Market residual momentum, using the available tradable cross-section only.
    median_trend = float(np.median([x["t30"] for x in feat.values()]))
    for x in feat.values():
        x["mktres"] = x["t30"] - median_trend

    # Defensive regime overlay uses breadth and volatility, not observation-only assets.
    breadth = float(np.mean([x["t30"] > 0 for x in feat.values()]))
    medvol = float(np.median([x["vol"] for x in feat.values()]))
    stress = breadth < 0.50 or medvol > 0.018
    ranks = {k: rank_cs({s: x[k] for s, x in feat.items()}) for k in FACTORS}
    score = {s: sum(weight * ranks[k][s] for k, weight in FACTORS.items()) for s in ASSETS}
    if stress:
        for s in ("XAU", "US10Y", "CN10Y"):
            score[s] += 0.55
        for s in ("BTC", "ETH", "WTI"):
            score[s] -= 0.40
    invvol = {s: medvol / x["vol"] for s, x in feat.items()}
    target = make_weights(score, invvol)
    if set(target) == set(ASSETS) and all(np.isfinite(v) and v >= 0 for v in target.values()):
        rebalance_to_weights(target)


def strategy():
    return cross_asset_strategy()

